import logging
import re

from robot.libraries.DateTime import convert_time

from taf.collectors.core import core
from taf.collectors.pmcounters.factory import PmCounterCollectorFactorySelector

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class pmcounters(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _factory_selector = PmCounterCollectorFactorySelector()

    def create_pm_collector(self, name, webservice, for_last=None, intervals=None, timeout=None, **kwargs):
        """
        Create PM Collector from given configuration

        :param name: alias name of the collector
        :param dict webservice: ADMIN API setup info, see `setup_admin <https://\
                                taf-sbts-oam-coam-admin.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                interface.html#taf.sbts.oam.coam.admin.interface.admin.setup_admin>`_,
                                additionally the following parameter name abbreviations are supported:
                                 * "host" instead of "bts_host"
                                 * "port" instead of "bts_port"
                                 * "user" instead of "username"
        :param str for_last: (optional) `Time as time string
            <https://robotframework.org/robotframework/3.0.4/RobotFrameworkUserGuide.html#time-format>`_
            by default no criteria
        :param str intervals: (optional) comma separated interval values, by default all values allowed
        :param timeout: (optional) How long to wait for the server to send
            data before giving up, as a float. default : 120 secs
        :type timeout: float


        :return: created object of CoamPmCounterCollector
        :rtype: CoamPmCounterCollector
        """
        configuration = {
            'name': name,
            'webservice': webservice}
        if for_last is not None:
            configuration["for_last"] = convert_time(for_last, 'timedelta')
        if intervals is not None:
            configuration["intervals"] = re.findall(r'\d+', intervals)
        if timeout is not None:
            configuration["timeout"] = float(timeout)
        if kwargs:
            logger.warning("Given parameters {kwargs} will be ignored")
        logger.info("Creating PM Collector with alias name " + name)
        pmcounters_collector = self._factory_selector.create(
            configuration=configuration,
            existing_arguments={})
        self.set_alias(name, pmcounters_collector)
        logger.info("PM Collector created successfully")

    def create_coam_vcu_pm_collector(self, name, webservice, timeout=None, for_last=None, intervals=None):

        """
        Create cOAM VCU PM Collector from given configuration which will used
        for vRAN 2.0/4.0, Kubernetes containers, PM file collection via OAM

        :param name: alias name of the collector
        :param dict webservice: ADMIN API setup info, see `connect_to <https://\
                                taf-gnb-oam-coam-cu.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface.html\
                                #taf.gnb.oam.coam.cu.interface.cu.connect_to>`_,
                                additionally the following parameter name abbreviations are supported:
                                 * "user" instead of "username"
                                 * "release" instead of "cu_version"
        :param timeout: (optional) How long to wait for the server to send
            data before giving up, as a float, or a :ref:`(connect timeout,
            read timeout) <timeouts>` tuple.
        :type timeout: float or tuple
        :param str for_last: (optional) `Time as time string
            <https://robotframework.org/robotframework/3.0.4/RobotFrameworkUserGuide.html#time-format>`_
            by default no criteria
        :param str intervals: (optional) comma separated interval values, by default all values allowed


        :return: created object of CoamVCUPmCounterCollector
        :rtype: CoamVCUPmCounterCollector
        """
        configuration = {
            'name': name,
            'oam_type': 'coam_vcu',
            'webservice': webservice}
        if timeout is not None:
            configuration["timeout"] = timeout
        if for_last is not None:
            configuration["for_last"] = convert_time(for_last, 'timedelta')
        if intervals is not None:
            configuration["intervals"] = re.findall(r'\d+', intervals)
        logger.info("Creating Coam VCU PM Collector with alias name " + name)
        coam_vcu_pmcounters_collector = self._factory_selector.create(
            configuration=configuration,
            existing_arguments={})
        logger.info("Coam VCU PM Collector created successfully")
        self.set_alias(name, coam_vcu_pmcounters_collector)

